71	/** UI slot declaration extracted from plugin manifest */
72	type PluginUiSlotDeclaration = NonNullable<NonNullable<PaperclipPluginManifestV1["ui"]>["slots"]>[number];
73	/** Launcher declaration extracted from plugin manifest */
74	type PluginLauncherDeclaration = NonNullable<PaperclipPluginManifestV1["launchers"]>[number];
75	
76	/**
77	 * Normalized UI contribution for frontend slot host consumption.
78	 * Only includes plugins in 'ready' state with non-empty slot declarations.
79	 */
80	type PluginUiContribution = {
81	  pluginId: string;
82	  pluginKey: string;
83	  displayName: string;
84	  version: string;
85	  updatedAt: string;
86	  /**
87	   * Relative path within the plugin's UI directory to the entry module
88	   * (e.g. `"index.js"`). The frontend constructs the full import URL as
89	   * `/_plugins/${pluginId}/ui/${uiEntryFile}`.
90	   */
91	  uiEntryFile: string;
92	  slots: PluginUiSlotDeclaration[];
93	  launchers: PluginLauncherDeclaration[];
94	};
